SELECT DISTINCT sid FROM shop_list
WHERE platform_code = #{platformCode}
AND status = #{status}
AND sid IS NOT NULL AND sid != ''
AND pull_enabled = 1 AND lingxing_present = 1

SELECT * FROM shop_list

    AND platform_code = #{platformCode}

        AND (store_name LIKE CONCAT('%', #{keyword}, '%') OR sid = #{keyword})

    AND pull_enabled = #{pullEnabled}
    AND lingxing_present = #{lingxingPresent}

ORDER BY platform_code, store_name

SELECT * FROM shop_list
WHERE platform_code = #{platformCode}
AND status = #{status}
ORDER BY store_name

SELECT * FROM shop_list
WHERE platform_code = #{platformCode}
  AND TRIM(store_name) = TRIM(#{storeName})
AND status = #{status}
ORDER BY id
